"""Printed 202–203: medians, altitudes, bisectors and source discrepancies."""
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path
def median_figure():
 a,b,c=(110,260),(430,260),(270,55)
 ap,bp,cp=(350,157.5),(190,157.5),(270,260)
 return geometry('Figure 7.25','Figure 7.25 — source triangle with three medians and midpoint labels',[path([a,b,c,a]),path([a,ap]),path([b,bp]),path([c,cp])],[(72,280,'A(8,−5)'),(408,280,'B(6,5)'),(255,42,'C(−6,9)'),(356,157,'A′'),(163,157,'B′'),(260,283,'C′')])
def altitude_figure():
 a,b,c=(80,110),(425,60),(340,285)
 def foot(p,q,r):
  v=(r[0]-q[0],r[1]-q[1]);t=((p[0]-q[0])*v[0]+(p[1]-q[1])*v[1])/(v[0]**2+v[1]**2);return(q[0]+t*v[0],q[1]+t*v[1])
 ap,bp,cp=foot(a,b,c),foot(b,a,c),foot(c,a,b)
 return geometry('Figure 7.26','Figure 7.26 — source altitude construction, with actual perpendicular feet in a schematic triangle',[path([a,b,c,a]),path([a,ap]),path([b,bp]),path([c,cp])],[(40,106,'A(−7,4)'),(400,48,'B(9,6)'),(318,307,'C(7,−10)'),(ap[0]+6,ap[1]+7,'A′'),(bp[0]-23,bp[1]+7,'B′'),(cp[0]-10,cp[1]-10,'C′')])
BISECTOR_TRIANGLE=geometry('Figure 7.27','Figure 7.27 — original source triangle labels, including A(−8,4) that differs from the question',[path([(100,260),(430,245),(270,70),(100,260)])],[(53,280,'A(−8,4)'),(407,266,'B(10,8)'),(246,55,'C(6,−12)')])
def bisector_figure():
 a,b,c=(250,45),(100,270),(430,250)
 d,e,f=((b[0]+c[0])/2,(b[1]+c[1])/2),((a[0]+c[0])/2,(a[1]+c[1])/2),((a[0]+b[0])/2,(a[1]+b[1])/2)
 # Solve the two equidistance equations for the common circumcenter.
 aa,bb,cc=2*(b[0]-a[0]),2*(b[1]-a[1]),b[0]**2+b[1]**2-a[0]**2-a[1]**2
 dd,ee,ff=2*(c[0]-a[0]),2*(c[1]-a[1]),c[0]**2+c[1]**2-a[0]**2-a[1]**2
 det=aa*ee-bb*dd;g=((cc*ee-bb*ff)/det,(aa*ff-cc*dd)/det)
 return geometry('Figure 7.28','Figure 7.28 — three perpendicular bisectors through midpoints D,E,F meeting at G',[path([a,b,c,a]),path([d,g]),path([e,g]),path([f,g])],[(245,30,'A'),(82,286,'B'),(435,265,'C'),(d[0]-8,d[1]+22,'D'),(e[0]+7,e[1],'E'),(f[0]-23,f[1],'F'),(g[0]+6,g[1]-5,'G')])
PAGES=[page('105_page_2.jpg',202,[heading('Example 22'),paragraph('Find the equation of the median of a triangle having vertices are A(8,−5), B(6,5) and C(−6,9).'),heading('Solution'),paragraph('If C′ is mid point of side AB of ΔABC Then its co-ordinates are given as'),eq(r'\left(\frac{8+6}2,\frac{-5+5}2\right)=(7,0)'),paragraph('Since, the median CC′ passes through points C and C′, using the two-point form of the equation of a straight line, the equation of median CC′ can be found as'),eq(r'\frac{y-0}{9-0}=\frac{x-7}{-6-7}\ \Rightarrow\frac y9=\frac{x-7}{-13}\ \Rightarrow\ 13y+9x-63=0'),median_figure(),paragraph('If A′ is the midpoint of side BC of ΔABC then its coordinates are given as'),eq(r'\left(\frac{6-6}2,\frac{5+9}2\right)=\left(\frac02,\frac{14}2\right)=(0,7)'),paragraph('Since, the median AA′ passes through the point A and A′ respectively. By using the two point form of the equation of a straight line, the equation of median AA′ can be found as'),eq(r'\frac{y-7}{7-(-5)}=\frac{x-0}{0-8}\ \Rightarrow\frac{y-5}{12}=\frac x{-8}\ \Rightarrow\ -8y-12x+40=0'),paragraph('If B′ is the midpoint of side AC of ΔABC then its coordinate are given as'),eq(r'\left(\frac{8-6}2,\frac{-5+9}2\right)=\left(\frac22,\frac42\right)=(1,2)'),paragraph('Since, the median BB′ passes through the point B and B′ respectively. By using the two point form of the equation of a straight line, the equation of median BB′ can be found as'),eq(r'\frac{y-2}{2-5}=\frac{x-1}{1-6}\ \Rightarrow\frac{y-2}{-3}=\frac{x-1}{-5}\ \Rightarrow\ 3x-5y+7=0'),note('The source AA′ line changes y−7 to y−5 and ends with a wrong constant 40. Through A(8,−5) and A′(0,7), the correct median is 12x+8y−56 = 0, or 3x+2y−14 = 0. The other two source median equations are correct.'),heading('B. Equation of altitude of a triangle'),paragraph('Altitude of a triangle is the perpendicular drawn from the vertex of the triangle to the opposite side. This is also known as the height of the triangle. Mostly it is used to find the area of the triangle. Look at the following example the procedure to find the equation of altitude is illustrated in example 22.'),heading('Example 23'),paragraph('Find the equation of altitude of triangle ABC having vertices are A(−7,4), B(9,6) and C(7,−10).'),heading('Solution'),paragraph('First we find slope of side'),eq(r'AB=m_1=\frac{6-4}{9+7}=\frac2{16}=\frac18'),altitude_figure(),paragraph('The altitude CC′ is perpendicular to side AB, so the slope of'),eq(r'CC′=\frac1{m_1}=-8'),paragraph('Since the altitude CC′ passes through the point C(7,−10), by using the point slope form of the equation of a line, the equation of CC′ is'),eq(r'y-(-10)=-8(x-7)'),eq(r'\Rightarrow\ y+10=-8x+56\ \Rightarrow\ 8x+y-46=0'),paragraph('Which is the equation of the altitude from C to AB.'),eq(r'\mathrm{The\ slope\ of\ side}\ BC=m_2=\frac{-10-6}{7-9}=\frac{-16}{-2}=8')]),page('106_page_1.jpg',203,[paragraph('The altitude AA′ is perpendicular to side BC, so the slope of AA′ = 1/m₂ = −1/8.'),paragraph('Since, the altitude passes through the point A(−7,4), by using the point slope form of the equation of a line, the equation of AA′ is'),eq(r'y-4=-\frac18(x+7)\ \Rightarrow\ x+8y-27=0'),paragraph('Which is the equation of the altitude from A to BC.'),eq(r'\mathrm{The\ slope\ of\ side}\ AC=m_3=\frac{-10-(-7)}{7-4}=\frac{-3}3=-1'),paragraph('The altitude BB′ is perpendicular to side AC. So,'),eq(r'\mathrm{The\ slope\ of}\ BB′=-\frac1{m_3}=-\frac1{-1}=1'),paragraph('since, the altitude passes through the point B(9,6), By using the point slope form of the equation of a line, the equation of BB′ is'),eq(r'y-6=1(x-9)\ \Rightarrow\ x-y-3=0'),paragraph('Which is the equation of the altitude from B to AC.'),note('For perpendicular finite slopes use −1/m, not the positive 1/m printed for CC′ and AA′. From y−4 = −(x+7)/8, the correct rearrangement is x+8y−25 = 0, not the source’s −27. The AC slope calculation mixes x and y coordinates; the correct quotient is (−10−4)/(7−(−7)) = −14/14 = −1. It happens to give the same slope. The altitude paragraph’s reference to example 22 should identify Example 23.'),heading('C. Equation of bisector of a triangle'),paragraph('The bisector of a triangle is a line perpendicular to the side and passing through its midpoint. The three perpendicular bisectors of the sides of a triangle meet in a single point. The procedure to find the equation of a bisector is illustrate in the following example.'),heading('Example 24'),paragraph('Find the equation of the right bisector of a triangle having points are A(−7,4), B(10,8) and C(6,−12).'),heading('Solution'),paragraph('Since, the equation of a perpendicular bisector is given as,'),eq(r'y-\frac{y_1+y_2}2=-\frac{x_2-x_1}{y_2-y_1}\left(x-\frac{x_1+x_2}2\right)','i'),paragraph('For bisector of A(−7,4) and B(10,8) put the values in equation (i):'),eq(r'y-\frac{8+4}2=\frac{10+7}{8-4}\left(x-\frac{10-7}2\right)\ \Rightarrow\ y-6=\frac{17}4\left(x-\frac32\right)\ \Rightarrow\ 34x-8y-3=0'),paragraph('For bisector of B(10,8) and C(6,−12) put the values in equation (i):'),eq(r'y-\frac{8-12}2=-\frac{6-10}{-12-8}\left(x-\frac{10+6}2\right)'),eq(r'\Rightarrow\ y+2=-\frac15(x-8)\ \Rightarrow\ x+5y+2=0'),BISECTOR_TRIANGLE,paragraph('For bisector of A(−7,4) and C(6,−12) put the values in equation (i):'),eq(r'y-\frac{4-12}2=-\frac{6+7}{-12+4}\left(x-\frac{-7+6}2\right)'),eq(r'\Rightarrow\ y+4=\frac{13}8\left(x+\frac12\right)\ \Rightarrow\ 26x-16y-51=0'),note('The source drops the required minus sign in its AB substitution, so its first final bisector is incorrect. In AC it uses −12+4 instead of −12−4 in the slope denominator, producing an incorrect factor 13/8 rather than 13/16. Correct bisectors for the question’s A(−7,4), B(10,8), C(6,−12) are 34x+8y−99 = 0; x+5y+2 = 0; and 26x−32y−115 = 0. Figure 7.27 labels A(−8,4), differing from the question’s −7; the original label is preserved in the source reconstruction and the learning solution uses the stated question coordinates. “Right bisector” here means perpendicular bisector of a side, distinct from an angle bisector.'),heading('7.7.3 Show that, three right bisectors, three medians and three altitudes of a triangle are concurrent'),heading('i. Three right bisectors of a triangle are concurrent'),paragraph('To show the concurrency of the three right bisectors of a triangle, the procedure developed is as under:'),paragraph('Let ABC be a triangle, whose vertices are A(x₁,y₁), B(x₂,y₂) and C(x₃,y₃), D, E, F are the midpoints of the sides BC, CA, AB of a triangle ABC whose coordinates are respectively:'),bisector_figure()])]
for p in PAGES:
 p.update(title='PLANE ANALYTIC GEOMETRY STRAIGHT LINE',visualStatus='Complete source median/altitude/bisector examples with four native figures, including preserved inconsistent source label',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':105 if p['page']==202 else 106,'side':'right' if p['page']==202 else 'left','reason':'All midpoint coordinates, wrong source constants, sign omissions and figure-label mismatch visually checked'})
EXAMPLES=[]
for n,q,steps,ans,pages in [
('22','Find the medians of A(8,−5), B(6,5), C(−6,9).',['A′, the midpoint of BC, is ((6−6)/2,(5+9)/2) = (0,7).','The median from A is y+5 = (−3/2)(x−8), giving 3x+2y−14 = 0.','B′, the midpoint of CA, is ((−6+8)/2,(9−5)/2) = (1,2).','The median from B is y−2 = (3/5)(x−1), giving 3x−5y+7 = 0.','C′, the midpoint of AB, is ((8+6)/2,(−5+5)/2) = (7,0).','The median from C is y = −9(x−7)/13, giving 9x+13y−63 = 0.','Each equation passes through its stated vertex and opposite-side midpoint. The common centroid is ((8+6−6)/3,(−5+5+9)/3) = (8/3,3), which satisfies all three.','The source’s AA′ equation uses an incorrect constant; the corrected median is derived from the actual points and checked independently.'],'AA′: 3x+2y−14 = 0; BB′: 3x−5y+7 = 0; CC′: 9x+13y−63 = 0.',[202]),
('23','Find the altitudes of A(−7,4), B(9,6), C(7,−10).',['AB has slope (6−4)/(9−(−7)) = 1/8, so the altitude from C has slope −8.','Through C, y+10 = −8(x−7), giving 8x+y−46 = 0.','BC has slope (−10−6)/(7−9) = 8, so the altitude from A has slope −1/8.','Through A, y−4 = −(x+7)/8, giving x+8y−25 = 0.','CA has slope (4−(−10))/(−7−7) = −1, so the altitude from B has slope 1.','Through B, y−6 = x−9, giving x−y−3 = 0.','Each equation contains its vertex, and each altitude slope times the corresponding opposite-side slope is −1.','Solving x+8y = 25 and x−y = 3 gives the orthocenter H(49/9,22/9). It also satisfies 8x+y = 46.','The source’s AA′ final constant −27 and its mixed-coordinate AC quotient are retained in the lesson and corrected in these verified steps.'],'From A: x+8y−25 = 0; from B: x−y−3 = 0; from C: 8x+y−46 = 0.',[202,203]),
('24','Find the perpendicular bisectors for A(−7,4), B(10,8), C(6,−12).',['A point X(x,y) on the bisector of endpoints U,V satisfies (V−U)·(X−(U+V)/2) = 0. This handles vertical and horizontal sides without dividing by a slope.','For AB, the midpoint is (3/2,6) and V−U = (17,4).','Thus 17(x−3/2)+4(y−6) = 0; multiplying by 2 gives 34x+8y−99 = 0.','For BC, the midpoint is (8,−2) and C−B = (−4,−20).','Thus −4(x−8)−20(y+2) = 0, giving x+5y+2 = 0.','For AC, the midpoint is (−1/2,−4) and C−A = (13,−16).','Thus 13(x+1/2)−16(y+4) = 0; multiplying by 2 gives 26x−32y−115 = 0.','Each equation contains the midpoint and has a normal parallel to the side, proving perpendicularity.','The common point is (511/162,−167/162); substituting it in all three equations gives zero. The source’s AB sign and AC denominator errors would fail these checks.','The source figure labels A(−8,4); this solution follows the question’s A(−7,4) and makes the mismatch explicit.'],'AB: 34x+8y−99 = 0; BC: x+5y+2 = 0; AC: 26x−32y−115 = 0.',[203])]:
 EXAMPLES.append({'num':n,'title':'Triangle Medians' if n=='22' else 'Triangle Altitudes' if n=='23' else 'Perpendicular Bisectors','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'pageStart':min(pages),'pageEnd':max(pages),'verification':'All source vertices, equations and source errors visually checked'}],**({'sourceQuestionBlocks':[median_figure()]} if n=='22' else {'sourceQuestionBlocks':[altitude_figure()]} if n=='23' else {'sourceQuestionBlocks':[BISECTOR_TRIANGLE]})})
